"""Protocol guards for the paired agent evaluation: what a results file is bound to, how much
it may spend, and how often a held-out task set may be opened.

Pure functions only, so the rules are tested without running an agent.
"""

from __future__ import annotations

import hashlib
import json
from pathlib import Path
from typing import Any

PROTOCOL = "agent-swe-v2"


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def spend(tokens: dict[str, int]) -> int:
    """Tokens billed for one run, unweighted: every input, output and cache token. Prices vary
    by provider and cache tier, so the cap is in tokens; USD is the token counts times a price
    the operator applies to the recorded counts."""
    return sum(tokens.get(k, 0) for k in ("input", "output", "cache_read", "cache_write"))


def spent(rows: list[dict[str, Any]]) -> int:
    return sum(spend(r["tokens"]) for r in rows if isinstance(r.get("tokens"), dict))


def may_start(spent_so_far: int, cap: int | None) -> bool:
    """Whether another run may start. In-flight runs finish, so the realized total can exceed the
    cap by at most the number of concurrent jobs times one run's spend."""
    return cap is None or spent_so_far < cap


def check_manifest(path: Path, manifest: dict[str, Any]) -> None:
    """Write the manifest beside a new results file, or refuse to resume under a different one.

    A results file is only comparable to runs made under the same tasks, code, prompt, arm
    configuration and agent binary. Resuming under a changed protocol mixes two experiments."""
    if not path.exists():
        path.write_text(json.dumps(manifest, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        return
    recorded = json.loads(path.read_text(encoding="utf-8"))
    diff = sorted(k for k in set(recorded) | set(manifest) if recorded.get(k) != manifest.get(k))
    if diff:
        raise SystemExit(
            f"{path} was recorded under a different protocol ({', '.join(diff)} changed); "
            "start a new results file instead of resuming"
        )


def heldout_open(log: Path, tasks_sha: str, out: Path) -> None:
    """A held-out task set is opened once. Resuming the same results file is allowed; a second
    file on the same set is a second look, which the protocol forbids."""
    entries = [json.loads(line) for line in log.read_text().splitlines()] if log.exists() else []
    for entry in entries:
        if entry["tasks_sha256"] == tasks_sha and entry["out"] != str(out):
            raise SystemExit(
                f"held-out tasks {tasks_sha[:12]} were already opened by {entry['out']}; "
                "a held-out set is one look, so write a new held-out set instead"
            )
    if not any(e["tasks_sha256"] == tasks_sha and e["out"] == str(out) for e in entries):
        with log.open("a", encoding="utf-8") as file:
            file.write(json.dumps({"tasks_sha256": tasks_sha, "out": str(out)}) + "\n")

"""Why agents engage with or ignore OXIDE, from the retained traces of a results file.

    uv run python scripts/agent_eval diagnose RESULTS.jsonl

Each OXIDE-arm run falls in one class, decided by its trace and the gold patch's files:

- not connected: the OXIDE tool never reached the agent's session (no `mcp connected` line)
- connected, never called: the agent had the tool and did not use it
- called after builtins read gold: builtin tools had already opened a file the gold patch changes
- called first, gold surfaced: the first OXIDE call listed a gold file, which builtins had not yet opened
- called first, gold not surfaced: the OXIDE calls listed no gold file

Rows without a `trace` field (older results) use the newest run directory holding their key.
"""

from __future__ import annotations

import collections
import json
import re
from pathlib import Path
from typing import Any

import run
import tasks

CLASSES = (
    "not connected",
    "connected, never called",
    "called after builtins read gold",
    "called first, gold surfaced",
    "called first, gold not surfaced",
)


def calls_of(events: str) -> list[dict[str, Any]]:
    calls: list[dict[str, Any]] = []
    for line in events.splitlines():
        try:
            event = json.loads(line)
        except ValueError:
            continue
        if event.get("type") == "tool_use":
            state = event["part"].get("state", {})
            calls.append(
                {
                    "tool": event["part"].get("tool", "?"),
                    "input": state.get("input") or {},
                    "output": str(state.get("output", "")),
                }
            )
    return calls


def gold_paths(gold_patch: str) -> set[str]:
    return set(re.findall(r"^\+\+\+ b/(\S+)", gold_patch, re.MULTILINE))


def read_path(call: dict[str, Any]) -> str:
    return str(call["input"].get("path") or call["input"].get("filePath") or "")


def surfaced(output: str) -> set[str]:
    """File paths an OXIDE context bundle lists, from its `### path:start-end` headers."""
    return set(re.findall(r"^### (\S+?):\d+", output, re.MULTILINE))


def degraded(output: str) -> list[str]:
    return [line.removeprefix("# degraded: ") for line in output.splitlines() if "# degraded:" in line]


def classify(calls: list[dict[str, Any]], gold: set[str], connected: int) -> str:
    if connected == 0:
        return CLASSES[0]
    oxide = [i for i, c in enumerate(calls) if c["tool"].startswith("oxide")]
    if not oxide:
        return CLASSES[1]
    builtin_read = any(
        calls[i]["tool"] == "read"
        and any(read_path(calls[i]) == g or read_path(calls[i]).endswith("/" + g) for g in gold)
        for i in range(oxide[0])
    )
    if builtin_read:
        return CLASSES[2]
    seen = set().union(*(surfaced(calls[i]["output"]) for i in oxide))
    return CLASSES[3] if gold & seen else CLASSES[4]


def trace_dir(row: dict[str, Any]) -> Path:
    if "trace" in row:
        return tasks.CACHE / row["trace"]
    key = f"{row['task']}.{row['arm']}.{row['rep']}"
    roots = sorted(
        (d for d in (tasks.CACHE / "runs").iterdir() if (d / key / "events.jsonl").exists()),
        key=lambda d: d.name,
    )
    if not roots:
        raise FileNotFoundError(f"no trace for {key}")
    return roots[-1] / key


def diagnose(results: Path) -> str:
    rows = [json.loads(line) for line in results.read_text(encoding="utf-8").splitlines()]
    latest: dict[tuple[str, str, int], dict[str, Any]] = {}
    for row in rows:
        latest[(row["task"], row["arm"], row["rep"])] = row  # the last attempt is the one scored
    scored = [r for r in latest.values() if r.get("status") == "ok"]
    by_split = {s: {t["id"]: t for t in tasks.load(s)} for s in ("dev", "heldout")}
    counts: collections.Counter[str] = collections.Counter()
    resolved: collections.Counter[str] = collections.Counter()
    reasons: collections.Counter[str] = collections.Counter()
    calls_per_run: list[int] = []
    control = [r for r in scored if r["arm"] == "control"]
    for row in (r for r in scored if r["arm"] == "oxide"):
        base = trace_dir(row)
        calls = calls_of((base / "events.jsonl").read_text(encoding="utf-8"))
        task = by_split[row.get("split", "dev")][row["task"]]
        cls = classify(calls, gold_paths(task["gold_patch"]), run.connected(base / "data", "oxide"))
        counts[cls] += 1
        resolved[cls] += bool(row["resolved"])
        oxide_outputs = [c["output"] for c in calls if c["tool"].startswith("oxide")]
        calls_per_run.append(len(oxide_outputs))
        for output in oxide_outputs:
            reasons.update(degraded(output))
    lines = [
        f"control resolved {sum(bool(r['resolved']) for r in control)}/{len(control)}",
        f"oxide arm: {len(scored)} scored latest attempts",
        "",
        "| class | runs | resolved |",
        "|---|---:|---:|",
    ]
    lines += [f"| {c} | {counts[c]} | {resolved[c]} |" for c in CLASSES if counts[c]]
    lines += ["", f"oxide calls per called run: {sorted(collections.Counter(calls_per_run).items())}"]
    lines += [f"degraded {n}x: {reason}" for reason, n in reasons.most_common(8)]
    return "\n".join(lines)

